export const envelope = [54, 48, 54];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Array(W * H * D).fill(null);

  function setV(x, y, z, block) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return;
    grid[x + y * W + z * W * H] = block;
  }

  function getV(x, y, z) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return null;
    return grid[x + y * W + z * W * H];
  }

  // --- Theme & Palette Resolution ---
  const pDarkPrism = "minecraft:dark_prismarine";
  const pPrismBricks = "minecraft:prismarine_bricks";
  const pPrism = "minecraft:prismarine";
  const pSeaLantern = "minecraft:sea_lantern";
  const pPearlescent = "minecraft:pearlescent_froglight";
  const pOchre = "minecraft:ochre_froglight";
  const pBone = "minecraft:bone_block[axis=y]";
  const pBoneX = "minecraft:bone_block[axis=x]";
  const pBoneZ = "minecraft:bone_block[axis=z]";
  const pSculk = "minecraft:sculk";
  const pCyan = "minecraft:cyan_terracotta";
  const pSmoothSand = "minecraft:smooth_sandstone";
  const pTeethDown = "minecraft:pointed_dripstone[thickness=tip,vertical_direction=down]";
  const pTeethUp = "minecraft:pointed_dripstone[thickness=tip,vertical_direction=up]";

  // Seawall & Classical Hellenist architectural elements
  const stonePrimary = (api.theme && api.theme.stone && api.theme.stone.primary) || "minecraft:smooth_quartz";
  const stoneAccent = (api.theme && api.theme.stone && api.theme.stone.accent) || "minecraft:quartz_pillar[axis=y]";
  const stoneWall = (api.theme && api.theme.stone && api.theme.stone.wall) || "minecraft:diorite_wall";
  const groundPavement = (api.theme && api.theme.ground && api.theme.ground.pavement) || "minecraft:stone_bricks";
  const groundPlinth = (api.theme && api.theme.ground && api.theme.ground.plinth) || "minecraft:polished_andesite";
  const stoneSlab = "minecraft:smooth_quartz_slab[type=bottom]";
  const stoneStairsS = "minecraft:quartz_stairs[facing=south,half=bottom]";

  // --- Spline Utilities ---
  function catmullRom(p0, p1, p2, p3, t) {
    const t2 = t * t;
    const t3 = t2 * t;
    return 0.5 * (
      (2 * p1) +
      (-p0 + p2) * t +
      (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 +
      (-p0 + 3 * p1 - 3 * p2 + p3) * t3
    );
  }

  function sampleSpline(pts, tGlobal) {
    const n = pts.length;
    if (n === 1) return pts[0];
    const clampedT = Math.max(0, Math.min(n - 1 - 0.0001, tGlobal));
    const seg = Math.floor(clampedT);
    const u = clampedT - seg;

    const i0 = Math.max(0, seg - 1);
    const i1 = seg;
    const i2 = Math.min(n - 1, seg + 1);
    const i3 = Math.min(n - 1, seg + 2);

    const p0 = pts[i0], p1 = pts[i1], p2 = pts[i2], p3 = pts[i3];

    const x = catmullRom(p0.x, p1.x, p2.x, p3.x, u);
    const y = catmullRom(p0.y, p1.y, p2.y, p3.y, u);
    const z = catmullRom(p0.z, p1.z, p2.z, p3.z, u);

    const r0 = p0.r !== undefined ? p0.r : p0.rx;
    const r1 = p1.r !== undefined ? p1.r : p1.rx;
    const r2 = p2.r !== undefined ? p2.r : p2.rx;
    const r3 = p3.r !== undefined ? p3.r : p3.rx;
    const r = catmullRom(r0, r1, r2, r3, u);

    const ry0 = p0.ry !== undefined ? p0.ry : r0;
    const ry1 = p1.ry !== undefined ? p1.ry : r1;
    const ry2 = p2.ry !== undefined ? p2.ry : r2;
    const ry3 = p3.ry !== undefined ? p3.ry : r3;
    const ry = catmullRom(ry0, ry1, ry2, ry3, u);

    return { x, y, z, r, ry };
  }

  // --- Tentacle / Body Rasterizer ---
  function rasterizeLimb(pts, isMainTorso = false) {
    const n = pts.length;
    const steps = (n - 1) * 14;
    for (let s = 0; s <= steps; s++) {
      const t = (s / steps) * (n - 1);
      const c = sampleSpline(pts, t);
      const rx = c.r;
      const ry = c.ry;
      const rz = c.r;
      const maxR = Math.max(rx, ry);
      const iR = Math.ceil(maxR);

      for (let dx = -iR; dx <= iR; dx++) {
        for (let dy = -iR; dy <= iR; dy++) {
          for (let dz = -iR; dz <= iR; dz++) {
            const q = (dx * dx) / (rx * rx) + (dy * dy) / (ry * ry) + (dz * dz) / (rz * rz);
            if (q <= 1.0) {
              const vx = Math.round(c.x + dx);
              const vy = Math.round(c.y + dy);
              const vz = Math.round(c.z + dz);

              let mat = pDarkPrism;
              if (isMainTorso) {
                if (dy < -0.35 * ry) {
                  mat = ((vx + vz) % 3 === 0) ? pCyan : pPrism;
                } else if (dy > 0.4 * ry && Math.abs(dx) <= 1) {
                  mat = pDarkPrism;
                } else if (q > 0.65) {
                  mat = ((vx * 7 + vy * 13 + vz * 19) % 5 === 0) ? pPrismBricks : pDarkPrism;
                } else {
                  mat = pDarkPrism;
                }
              } else {
                // Tentacles: underside suckers and dark prismarine skin
                if (dy < -0.25 * ry || (dz < -0.3 * rz && dy < 0)) {
                  const suckerHash = Math.abs(Math.sin(t * 4.2 + dx * 0.5) * 100);
                  if (suckerHash % 5 < 1.2 && q > 0.6) {
                    mat = pPearlescent;
                  } else if (q > 0.55) {
                    mat = pSmoothSand;
                  } else {
                    mat = pPrism;
                  }
                } else if (q > 0.6) {
                  mat = ((vx + vy + vz) % 4 === 0) ? pPrismBricks : pDarkPrism;
                } else {
                  mat = pDarkPrism;
                }
              }
              setV(vx, vy, vz, mat);
            }
          }
        }
      }
    }
  }

  // --- 1. Classical Hellenist Seawall & Colonnade Promenade ---
  // Deck along Z = 2..8, Y = 11. Embankment down to Y = 8.
  for (let x = 2; x <= 51; x++) {
    for (let z = 2; z <= 8; z++) {
      // Wall core / foundation
      for (let y = 8; y <= 10; y++) {
        setV(x, y, z, groundPlinth);
      }
      // Pavement deck
      const isBorder = (z === 2 || z === 8 || x === 2 || x === 51);
      setV(x, 11, z, isBorder ? stonePrimary : groundPavement);
    }
    // Classical seawall parapet (intact at flanks, destroyed in center breach)
    if (x <= 14 || x >= 39) {
      setV(x, 12, 8, stoneWall);
      setV(x, 13, 8, stoneSlab);
    }
  }

  // Grand pier stairs at intact flanks descending to water
  for (let x = 3; x <= 6; x++) {
    setV(x, 10, 9, stoneStairsS);
    setV(x, 9, 10, stoneStairsS);
    setV(x, 8, 11, stoneStairsS);
  }
  for (let x = 47; x <= 50; x++) {
    setV(x, 10, 9, stoneStairsS);
    setV(x, 9, 10, stoneStairsS);
    setV(x, 8, 11, stoneStairsS);
  }

  // Classical Monumental Columns along the Promenade (Z = 4)
  const columnData = [
    { x: 8, intact: true },
    { x: 15, intact: false, brokenY: 15 },
    { x: 22, intact: false, brokenY: 12 }, // shattered stump under chest
    { x: 32, intact: false, brokenY: 13 }, // shattered stump
    { x: 43, intact: false, brokenY: 18, grabWrap: true }, // entwined by tentacle
    { x: 49, intact: true }
  ];

  for (const col of columnData) {
    const cx = col.x;
    // Column Plinth Base
    for (let dx = 0; dx <= 1; dx++) {
      for (let dz = 0; dz <= 1; dz++) {
        setV(cx + dx, 11, 4 + dz, groundPlinth);
        setV(cx + dx, 12, 4 + dz, stonePrimary);
      }
    }

    const maxY = col.intact ? 19 : col.brokenY;
    for (let y = 13; y <= maxY; y++) {
      setV(cx, y, 4, stoneAccent);
      setV(cx + 1, y, 4, stoneAccent);
      setV(cx, y, 5, stoneAccent);
      setV(cx + 1, y, 5, stoneAccent);
    }

    if (col.intact) {
      // Capital & Entablature
      for (let dx = -1; dx <= 2; dx++) {
        for (let dz = -1; dz <= 2; dz++) {
          setV(cx + dx, 20, 4 + dz, stonePrimary);
          setV(cx + dx, 21, 4 + dz, stonePrimary);
        }
      }
    }
  }

  // Shattered classical debris around the breach zone
  for (let rx = 16; rx <= 38; rx += 2) {
    for (let rz = 4; rz <= 12; rz += 2) {
      if ((rx + rz) % 3 === 0) {
        setV(rx, 8, rz, stonePrimary);
        setV(rx + 1, 8, rz, groundPavement);
        if ((rx * rz) % 4 === 0) {
          setV(rx, 9, rz, stoneAccent);
        }
      }
    }
  }

  // --- 2. Leviathan Main Torso & Neck Spline ---
  const mainSpine = [
    { x: 27, y: 8, z: 46, rx: 6.2, ry: 5.5 },
    { x: 27, y: 13, z: 38, rx: 6.8, ry: 6.5 },
    { x: 27, y: 21, z: 29, rx: 7.2, ry: 7.0 },
    { x: 27, y: 29, z: 20, rx: 6.4, ry: 6.2 },
    { x: 27, y: 35, z: 13, rx: 5.4, ry: 5.2 },
    { x: 27, y: 34, z: 7, rx: 4.8, ry: 4.5 },
    { x: 27, y: 33, z: 3, rx: 3.5, ry: 3.2 }
  ];
  rasterizeLimb(mainSpine, true);

  // --- 3. Dorsal Spines & Glowing Sea-Lantern Crest ---
  const finTValues = [0.6, 1.2, 1.8, 2.4, 3.0, 3.6, 4.2];
  for (const ft of finTValues) {
    const sp = sampleSpline(mainSpine, ft);
    const topY = Math.round(sp.y + sp.ry);
    const finHeight = 3 + Math.round(Math.sin((ft / 4.8) * Math.PI) * 3);

    for (let fh = 0; fh <= finHeight; fh++) {
      const fy = topY + fh;
      const fz = Math.round(sp.z + fh * 0.7);
      if (fy < H && fz < D) {
        setV(27, fy, fz, pSeaLantern);
        setV(26, fy, fz, pDarkPrism);
        setV(28, fy, fz, pDarkPrism);
        if (fh === finHeight) {
          setV(27, fy + 1, fz + 1, pBoneZ);
        }
      }
    }
  }

  // Continuous glowing dorsal ridge
  for (let st = 0.5; st <= 4.6; st += 0.15) {
    const sp = sampleSpline(mainSpine, st);
    const topY = Math.round(sp.y + sp.ry);
    setV(27, topY, Math.round(sp.z), pSeaLantern);
    setV(26, topY, Math.round(sp.z), pDarkPrism);
    setV(28, topY, Math.round(sp.z), pDarkPrism);
  }

  // --- 4. Leviathan Head, Gaping Maw, Teeth & Bioluminescent Lure ---
  // Upper Jaw & Armored Brow
  for (let hx = 23; hx <= 31; hx++) {
    for (let hz = 2; hz <= 11; hz++) {
      for (let hy = 34; hy <= 38; hy++) {
        const dEdge = Math.min(hx - 23, 31 - hx, hz - 2);
        if (hy >= 36 || dEdge >= 1) {
          setV(hx, hy, hz, pDarkPrism);
        }
      }
    }
  }

  // Horn crests sweeping back from brow
  for (let k = 0; k <= 5; k++) {
    setV(22 - Math.floor(k * 0.6), 38 + Math.floor(k * 0.6), 8 + k, pBone);
    setV(32 + Math.floor(k * 0.6), 38 + Math.floor(k * 0.6), 8 + k, pBone);
    setV(27, 39 + Math.floor(k * 0.7), 9 + k, pBone);
  }

  // Glowing Sea Lantern Eyes
  setV(22, 35, 7, pSeaLantern);
  setV(22, 35, 6, pDarkPrism);
  setV(32, 35, 7, pSeaLantern);
  setV(32, 35, 6, pDarkPrism);

  // Lower Jaw (dropped open)
  for (let hx = 23; hx <= 31; hx++) {
    for (let hz = 4; hz <= 11; hz++) {
      for (let hy = 27; hy <= 30; hy++) {
        const dEdge = Math.min(hx - 23, 31 - hx, hz - 4);
        if (hy === 27 || dEdge === 0) {
          setV(hx, hy, hz, pDarkPrism);
        }
      }
    }
  }

  // Carve Gaping Mouth Cavity
  for (let cx = 24; cx <= 30; cx++) {
    for (let cz = 3; cz <= 10; cz++) {
      for (let cy = 29; cy <= 34; cy++) {
        setV(cx, cy, cz, null);
      }
    }
  }

  // Bioluminescent deep gullet
  for (let gx = 25; gx <= 29; gx++) {
    for (let gy = 30; gy <= 33; gy++) {
      setV(gx, gy, 12, pSculk);
      setV(gx, gy, 13, pSeaLantern);
    }
  }

  // Teeth along upper & lower jaw rims
  for (let tx = 23; tx <= 31; tx += 2) {
    setV(tx, 34, 3, pTeethDown);
    setV(tx, 34, 5, pTeethDown);
    setV(tx, 34, 7, pTeethDown);
    setV(tx, 34, 9, pTeethDown);

    setV(tx, 29, 4, pTeethUp);
    setV(tx, 29, 6, pTeethUp);
    setV(tx, 29, 8, pTeethUp);
    setV(tx, 29, 10, pTeethUp);
  }

  // Bioluminescent Angler Lure Stalk & Bulb
  const lureStalk = [
    [27, 39, 6], [27, 41, 5], [27, 43, 3],
    [27, 44, 2], [27, 43, 0], [27, 41, 0], [27, 39, 0]
  ];
  for (const lp of lureStalk) {
    setV(lp[0], lp[1], lp[2], pDarkPrism);
  }
  // Glowing Lure Bulb
  for (let bx = 26; bx <= 28; bx++) {
    for (let by = 38; by <= 40; by++) {
      for (let bz = 0; bz <= 1; bz++) {
        setV(bx, by, bz, (bx === 27 && by === 39) ? pSeaLantern : pPearlescent);
      }
    }
  }

  // --- 5. Massive Grasping Coils & Tentacles ---

  // Tentacle 1 (Front-Left: Smashes onto Pier & Seawall)
  const tentacle1 = [
    { x: 22, y: 25, z: 23, r: 4.2 },
    { x: 16, y: 23, z: 17, r: 3.6 },
    { x: 11, y: 17, z: 12, r: 3.0 },
    { x: 7, y: 12, z: 8, r: 2.5 },
    { x: 6, y: 8, z: 6, r: 2.2 },
    { x: 7, y: 8, z: 4, r: 1.8 }
  ];
  rasterizeLimb(tentacle1);

  // Tentacle 2 (Front-Right: Grasping & Crushing Classical Pillar 5)
  const tentacle2 = [
    { x: 32, y: 25, z: 23, r: 4.2 },
    { x: 38, y: 24, z: 17, r: 3.6 },
    { x: 43, y: 19, z: 12, r: 3.0 },
    { x: 45, y: 14, z: 7, r: 2.6 },
    { x: 42, y: 11, z: 5, r: 2.2 },
    { x: 44, y: 8, z: 6, r: 1.8 }
  ];
  rasterizeLimb(tentacle2);

  // Tentacle 3 (Mid-Left: Sky Arch Whipping Coil)
  const tentacle3 = [
    { x: 21, y: 18, z: 32, r: 4.0 },
    { x: 14, y: 24, z: 28, r: 3.4 },
    { x: 7, y: 32, z: 22, r: 2.8 },
    { x: 4, y: 27, z: 15, r: 2.4 },
    { x: 4, y: 18, z: 10, r: 2.0 },
    { x: 6, y: 11, z: 8, r: 1.6 },
    { x: 9, y: 8, z: 9, r: 1.2 }
  ];
  rasterizeLimb(tentacle3);

  // Tentacle 4 (Mid-Right: Sky Arch Whipping Coil)
  const tentacle4 = [
    { x: 33, y: 18, z: 32, r: 4.0 },
    { x: 40, y: 25, z: 28, r: 3.4 },
    { x: 47, y: 33, z: 22, r: 2.8 },
    { x: 50, y: 27, z: 15, r: 2.4 },
    { x: 49, y: 18, z: 10, r: 2.0 },
    { x: 47, y: 11, z: 8, r: 1.6 },
    { x: 44, y: 8, z: 9, r: 1.2 }
  ];
  rasterizeLimb(tentacle4);

  // Tentacle 5 (Rear-Left: Deep Seabed Anchor)
  const tentacle5 = [
    { x: 21, y: 12, z: 38, r: 4.5 },
    { x: 14, y: 10, z: 42, r: 3.8 },
    { x: 8, y: 8, z: 46, r: 3.0 },
    { x: 5, y: 7, z: 49, r: 2.4 }
  ];
  rasterizeLimb(tentacle5);

  // Tentacle 6 (Rear-Right: Deep Seabed Anchor)
  const tentacle6 = [
    { x: 33, y: 12, z: 38, r: 4.5 },
    { x: 40, y: 10, z: 42, r: 3.8 },
    { x: 46, y: 8, z: 46, r: 3.0 },
    { x: 49, y: 7, z: 49, r: 2.4 }
  ];
  rasterizeLimb(tentacle6);

  // --- 6. Posterior Tail & Rearing Caudal Flukes ---
  const tailSpine = [
    { x: 27, y: 8, z: 46, r: 5.5 },
    { x: 27, y: 11, z: 50, r: 4.5 },
    { x: 27, y: 18, z: 52, r: 3.5 },
    { x: 27, y: 25, z: 49, r: 2.5 },
    { x: 27, y: 29, z: 45, r: 1.8 }
  ];
  rasterizeLimb(tailSpine);

  // Wide Serrated Whale / Sea-Serpent Caudal Flukes
  for (let fx = 16; fx <= 38; fx++) {
    const distCenter = Math.abs(fx - 27);
    if (distCenter >= 2) {
      const flukeY = Math.round(24 - distCenter * 0.4);
      const flukeZ = Math.round(49 + distCenter * 0.2);
      const finSpan = Math.round(5 - distCenter * 0.3);

      for (let fz = flukeZ - finSpan; fz <= flukeZ + finSpan; fz++) {
        if (fz >= 0 && fz < D && flukeY >= 0 && flukeY < H) {
          const isEdge = (fz === flukeZ - finSpan || fz === flukeZ + finSpan || distCenter >= 10);
          setV(fx, flukeY, fz, isEdge ? pBone : pDarkPrism);
          setV(fx, flukeY + 1, fz, isEdge ? pPrismBricks : pSeaLantern);
        }
      }
    }
  }

  // --- 7. Ground Conformance & Solid Foundation Skirt (Rule 6) ---
  const seatY = 8;
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let yMin = -1;
      let lowestBlock = null;

      for (let y = 0; y < H; y++) {
        const b = getV(x, y, z);
        if (b !== null) {
          yMin = y;
          lowestBlock = b;
          break;
        }
      }

      if (yMin !== -1) {
        const h = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(H - 1, seatY + h));

        // If ground drops below our structure (seabed, slope), extend downward solidly
        if (groundY < yMin) {
          let fillMat = pDarkPrism;
          if (lowestBlock.includes("quartz") || lowestBlock.includes("stone") || lowestBlock.includes("andesite") || lowestBlock.includes("diorite")) {
            fillMat = groundPlinth;
          } else if (lowestBlock.includes("prismarine")) {
            fillMat = pDarkPrism;
          }

          for (let y = groundY; y < yMin; y++) {
            setV(x, y, z, fillMat);
          }
        }
      }
    }
  }

  // --- 8. Emit Grid to World ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = grid[x + y * W + z * W * H];
        if (b !== null) {
          api.set(x, y, z, b);
        }
      }
    }
  }

  return {
    name: "colossal_leviathan",
    seatY: 8,
    anchors: {
      front: [27, 36, 0]
    }
  };
}

